// 1. 手写静态内部 Builder（Effective Java Item 2 推荐写法）
public final class HttpRequest {
    private final String url;
    private final String method;
    private final Map<String, String> headers;
    private final int timeoutMs;

    private HttpRequest(Builder b) {
        this.url = b.url;
        this.method = b.method;
        this.headers = Map.copyOf(b.headers);   // 防御性拷贝，外部改不动
        this.timeoutMs = b.timeoutMs;
    }

    public static Builder builder(String url) {
        return new Builder(url);                // 必填项放构造
    }

    public static class Builder {
        private final String url;               // 必填
        private String method = "GET";          // 默认值
        private Map<String, String> headers = new HashMap<>();
        private int timeoutMs = 3000;

        private Builder(String url) {
            this.url = Objects.requireNonNull(url, "url");
        }
        public Builder method(String m) { this.method = m; return this; }
        public Builder header(String k, String v) { this.headers.put(k, v); return this; }
        public Builder timeoutMs(int ms) { this.timeoutMs = ms; return this; }

        public HttpRequest build() {
            // 集中校验：跨字段约束放这里，比 setter 中分散校验靠谱
            if (timeoutMs <= 0) throw new IllegalArgumentException("timeoutMs>0");
            if ("POST".equals(method) && !headers.containsKey("Content-Type")) {
                throw new IllegalStateException("POST 必须带 Content-Type");
            }
            return new HttpRequest(this);
        }
    }
}

// 调用：必填走构造，可选走链式，build() 收口
HttpRequest req = HttpRequest.builder("https://api.x.com/users")
        .method("POST")
        .header("Content-Type", "application/json")
        .timeoutMs(5000)
        .build();

// 2. Lombok @Builder：编译期生成上面整套代码
@Builder(toBuilder = true)               // toBuilder=true 支持基于已有对象再造
public class User {
    private final String name;
    @Builder.Default                       // 默认值用这个注解，否则 Lombok 不识别
    private int age = 18;
}
User u1 = User.builder().name("张三").age(25).build();
User u2 = u1.toBuilder().age(26).build();  // 不可变更新

// 3. 真实库示例：OkHttp / StringBuilder
OkHttpClient client = new OkHttpClient.Builder()
        .connectTimeout(10, TimeUnit.SECONDS)
        .readTimeout(30, TimeUnit.SECONDS)
        .addInterceptor(new LoggingInterceptor())
        .build();

// StringBuilder（非线程安全，单线程拼字符串首选；并发场景才换 StringBuffer）
